ROOT.scriptdef:
CREATE PROCEDURE [CDN].[POS_EksportRelacjeGrupTowarow]
	@rowVersion bigint,
	@PointOfSaleId int
AS
BEGIN
SET NOCOUNT ON;	
	SELECT @rowVersion+1 AS [@RowVersion]
		,(		
		select distinct TwG_GIDNumer as [@Id], TwG_GIDNumer as [@ChildGroupId], twg_gronumer as [@ParentGroupId] 
			from cdn.PicoKonfig 
			join cdn.PicoStanowiska on pck_picoid = psa_pckid
			outer apply cdn.PobierzDrzewoGrupTowarowych(PcK_TwGENumer,DEFAULT,DEFAULT,1,DEFAULT,DEFAULT)
			join cdn.TwrGrupy on TwG_GIDNumer = GidNumer AND TwG_GIDTyp = Gidtyp 
			where psa_id = @PointOfSaleId and twg_gronumer >= 0 and TwG_GIDNumer <> PcK_TwGENumer
		for xml path('ProductGroupRelation'), type)
	for xml path('ProductGroupRelations')
	SET NOCOUNT OFF;	
END
